#!/usr/bin/env node
// Generates the typed models and one method per operation of the Python SDK from ../openapi.json
// (the live spec, https://api.pitchmentor.net/v1/openapi.json). Hand-written transport (retries, errors,
// pagination, webhooks) lives next to the generated file. Run: scripts/regen.sh (download + generate)
// or node codegen/generate.mjs (generate from the committed openapi.json).
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = JSON.parse(readFileSync(join(root, "openapi.json"), "utf8"));
// `ErrorResponse` is modelled by each SDK's hand-written error class
const { ErrorResponse: _errorSchema, ...schemas } = spec.components.schemas;

// ── IR ────────────────────────────────────────────────────

const refName = (ref) => ref.split("/").pop();
const isList = (s) => s?.type === "object" && s.properties?.data?.type === "array" && "next_cursor" in (s.properties ?? {});
const listItem = (s) => s.properties.data.items;

const ops = [];
for (const [path, methods] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(methods)) {
    const params = op.parameters ?? [];
    const ok = Object.entries(op.responses).find(([code]) => code.startsWith("2"))[1];
    const query = params.filter((p) => p.in === "query");
    ops.push({
      id: op.operationId,
      method: method.toUpperCase(),
      path,
      tag: op.tags?.[0] ?? "",
      summary: op.summary ?? "",
      description: op.description ?? "",
      scope: op["x-required-scope"] ?? null,
      pathParams: params.filter((p) => p.in === "path").map((p) => p.name),
      query,
      body: op.requestBody?.content?.["application/json"]?.schema ?? null,
      response: ok.content?.["application/json"]?.schema ?? null,
      csv: !!ok.content?.["text/csv"],
      paginated: query.some((p) => p.name === "cursor"),
      destructive: op["x-destructive"] === true, // flagged in docs, CLI (--yes) and MCP (destructiveHint)
    });
  }
}
// Events an endpoint can subscribe to (webhook.test is in `webhooks` but is only sent by testWebhookEndpoint)
const subscribableEvents = schemas.WebhookEndpoint.properties.events.items.enum;
const webhookEvents = Object.values(spec.webhooks ?? {}).map((w) => {
  const s = w.post.requestBody.content["application/json"].schema;
  return { type: s.properties.type.const, data: s.properties.data };
});

// ── naming ────────────────────────────────────────────────

const upper = (s) => s[0].toUpperCase() + s.slice(1);
const snake = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/-/g, "_").toLowerCase();
const goName = (s) =>
  s
    .split(/[_-]/)
    .map(upper)
    .join("")
    .replace(/Id(?=[A-Z]|$)/g, "ID")
    .replace(/Url(?=[A-Z]|$)/g, "URL");
const docLines = (op) =>
  [
    op.summary + (op.summary.endsWith(".") ? "" : "."),
    op.description.replace(/\n*Requires scope `[^`]+`\.$/, "").trim(),
    op.scope ? `Requires scope \`${op.scope}\`.` : "",
    op.destructive ? "DESTRUCTIVE: cannot be undone." : "",
  ].filter(Boolean);
const types = (s) => [s.type].flat().filter(Boolean);
const nullable = (s) => types(s).includes("null");
const HEADER = "Code generated by codegen/generate.mjs from openapi.json. DO NOT EDIT.";

// ── Python ────────────────────────────────────────────────

function genPython() {
  const classes = [];
  const lit = (v) => (typeof v === "string" ? JSON.stringify(v) : v === null ? "None" : String(v));

  function py(s, hint) {
    if (!s || Object.keys(s).filter((k) => k !== "description").length === 0) return "Any";
    if (s.$ref) return refName(s.$ref);
    if (s.allOf) return "dict[str, Any]";
    if (s.const !== undefined) return `Literal[${lit(s.const)}]`;
    const t = types(s);
    if (s.enum) return `Literal[${s.enum.map(lit).join(", ")}]${t.includes("null") ? " | None" : ""}`;
    if (t.length > 1) return t.map((x) => py({ ...s, type: x }, hint)).join(" | ");
    switch (t[0]) {
      case "string":
        return "str";
      case "integer":
        return "int";
      case "number":
        return "float";
      case "boolean":
        return "bool";
      case "null":
        return "None";
      case "array":
        return `list[${py(s.items, hint + "Item")}]`;
      case "object":
        if (isList(s)) return `Page[${py(listItem(s), hint)}]`;
        if (!s.properties) return "dict[str, Any]";
        pyClass(hint, s);
        return hint;
    }
    return "Any";
  }

  function pyClass(name, s, base = "TypedDict") {
    const req = new Set(s.required ?? []);
    const body = Object.entries(s.properties).map(([k, v]) => {
      const t = py(v, name + upper(k));
      return `    ${k}: ${req.has(k) ? t : `NotRequired[${t}]`}${v.description ? `\n    """${v.description}"""` : ""}`;
    });
    classes.push(`class ${name}(${base}):\n${body.join("\n") || "    pass"}\n`);
  }

  for (const [name, s] of Object.entries(schemas)) {
    if (s.allOf) {
      // allOf: [ref Base, {extra props}] → subclass
      pyClass(name, s.allOf[1], refName(s.allOf[0].$ref));
    } else pyClass(name, s);
  }
  for (const op of ops) if (op.body) py(op.body, `${upper(op.id)}Body`);

  const kw = (n) => (["from", "import", "class", "global", "in", "is"].includes(n) ? `${n}_` : snake(n));
  const methods = [];
  for (const op of ops) {
    const name = snake(op.id);
    const ret = op.response ? py(op.response, `${upper(op.id)}Response`) + (op.csv ? " | str" : "") : "Any";
    const sig = ["self", ...op.pathParams.map((p) => `${snake(p)}: str`)];
    if (op.body) sig.push(`body: ${upper(op.id)}Body`);
    const kwargs = op.query.map((p) => `${kw(p.name)}: ${py(p.schema, upper(op.id) + upper(p.name))}${p.required ? "" : " | None = None"}`);
    if (op.method === "POST") kwargs.push("idempotency_key: str | None = None");
    if (kwargs.length) sig.push("*", ...kwargs);
    const path = op.path.replace(/\{(\w+)\}/g, (_, p) => `{_seg(${snake(p)})}`);
    const call = [`"${op.method}"`, `${op.pathParams.length ? "f" : ""}"${path}"`];
    if (op.query.length) call.push(`query={${op.query.map((p) => `"${p.name}": ${kw(p.name)}`).join(", ")}}`);
    if (op.body) call.push("body=body");
    if (op.method === "POST") call.push("idempotency_key=idempotency_key");
    const doc = docLines(op).join("\n\n").split("\n").map((l) => (l ? `        ${l}` : "")).join("\n").trimStart();
    methods.push(`    def ${name}(${sig.join(", ")}) -> ${ret}:\n        """${doc}\n        """\n        return self._request(${call.join(", ")})  # type: ignore[no-any-return]\n`);
    if (op.paginated) {
      const item = py(listItem(op.response), "");
      const iterKw = op.query.filter((p) => p.name !== "cursor");
      const isig = ["self", ...op.pathParams.map((p) => `${snake(p)}: str`)];
      if (iterKw.length) isig.push("*", ...iterKw.map((p) => `${kw(p.name)}: ${py(p.schema, upper(op.id) + upper(p.name))}${p.required ? "" : " | None = None"}`));
      const fwd = [...op.pathParams.map(snake), ...iterKw.map((p) => `${kw(p.name)}=${kw(p.name)}`), "cursor=cursor"].join(", ");
      methods.push(
        `    def ${name}_iter(${isig.join(", ")}) -> Iterator[${item}]:\n` +
          `        """Iterates every item of :meth:\`${name}\`, fetching pages as needed."""\n` +
          `        return self._paginate(lambda cursor: self.${name}(${fwd}))\n`
      );
    }
  }

  const out = [
    `# ${HEADER}`,
    "from __future__ import annotations",
    "",
    "from typing import Any, Callable, Generic, Iterator, Literal, NotRequired, TypedDict, TypeVar",
    "from urllib.parse import quote",
    "",
    'T = TypeVar("T")',
    "",
    "",
    "class Page(TypedDict, Generic[T]):",
    "    data: list[T]",
    "    has_more: bool",
    "    next_cursor: str | None",
    "",
    "",
    ...classes.flatMap((c) => [c, ""]),
    `WEBHOOK_EVENT_TYPES = (${subscribableEvents.map((e) => JSON.stringify(e)).join(", ")})`,
    "",
    "",
    "def _seg(value: str) -> str:",
    '    return quote(value, safe="")',
    "",
    "",
    "class Operations:",
    '    """One method per API operation; transport is implemented by PitchMentor."""',
    "",
    "    def _request(self, method: str, path: str, *, query: dict[str, Any] | None = None, body: Any = None, idempotency_key: str | None = None) -> Any:",
    "        raise NotImplementedError",
    "",
    "    def _paginate(self, fetch_page: Callable[[str | None], Page[T]]) -> Iterator[T]:",
    "        raise NotImplementedError",
    "",
    methods.join("\n"),
  ];
  writeFileSync(join(root, "src/pitchmentor/_generated.py"), out.join("\n"));
}

genPython();
console.error(`generated ${ops.length} operations, ${Object.keys(schemas).length} schemas, ${webhookEvents.length} webhook events`);
